def perform(self):
    (ret, num_handles) = self.curl.perform()
    if ret != pycurl.E_CALL_MULTI_PERFORM and num_handles == 0:
        self.running = False
    (num, completed, failed) = self.curl.info_read()
    [self.close_request(com) for com in completed]
    for failed_request in failed:
        self.close_request(failed_request)
        print(f'Error: Request {failed_request} failed.')
    if not self.running:
        return False
    return True

def _make_datetime_field_compatible(self, field):
    if isinstance(field, datetime):
        if isinstance(field.tzinfo, tzlocal) and (not hasattr(field.tzinfo, '_hasdst')):
            return datetime(year=field.year, month=field.month, day=field.day, hour=field.hour, minute=field.minute, second=field.second, tzinfo=tzlocal())
    return field

def all_gather(self, tensor: torch.Tensor, mesh_dim: int=0) -> CommTensor:
    dim_group = self._dim_groups[mesh_dim]
    return all_gather(CommTensor(tensor.contiguous()), group=dim_group)

def fetch_metadata(self, url):
    repo_handler = None
    for handler in BaseHandler.registry.values():
        handler_instance = handler(url)
        if handler_instance.can_handle():
            repo_handler = handler_instance
            break
    if repo_handler is None:
        raise Exception('No handler available for the given URL.')
    (status, description) = repo_handler.fetch_metadata()
    return (status, description)

def __update(self):
    if self.__frame == self.__context.getFrame():
        return
    if self.__context.getFrame() not in self.__validFrames:
        raise ValueError('Invalid frame')
    self.clear()
    for plug in self.__variables.children():
        (value, name) = self.__variables.memberDataAndName(plug)
        if value is None:
            continue
        with IECore.IgnoredExceptions(Exception):
            value = value.value
        if isinstance(value, str):
            value = self.__context.substitute(value)
        self[name] = value
    self.__frame = self.__context.getFrame()

def command(self, command: AnyStr, site: Optional[SiteId]=None) -> None:
    command_str = _ensure_unicode(command).rstrip('\n')
    if not command_str.startswith('['):
        command_str = f'[{int(time.time())}] {command_str}'
    self.send_command(f'COMMAND {command_str}')

def _wait_for_task_token(self, env: Environment) -> None:
    callback_id = env.context_object_manager.context_object['Task']['Token']
    callback_endpoint = env.callback_pool_manager.get(callback_id)
    outcome = callback_endpoint.wait(timeout=30)
    if isinstance(outcome, CallbackOutcomeSuccess):
        outcome_output = json.loads(outcome.output)
        env.stack.append(outcome_output)
    elif isinstance(outcome, CallbackOutcomeFailure):
        raise CallbackOutcomeFailureError(callback_outcome_failure=outcome)
    else:
        raise NotImplementedError(f"Unsupported CallbackOutcome type '{type(outcome)}'.")

def get_user_tokens(self, bot, event, source, **rest):
    message_tokens = f'{source}, you have {source.tokens} tokens.'
    if self.settings['action_tokens'] == 'say':
        bot.send_message_to_user(source, message_tokens, event, method='say')
    elif self.settings['action_tokens'] == 'whisper':
        bot.send_message_to_user(source, message_tokens, event, method='whisper')
    elif self.settings['action_tokens'] == 'me':
        bot.send_message_to_user(source, message_tokens, event, method='me')
    elif self.settings['action_tokens'] == 'reply':
        if event.type in ['action', 'pubmsg']:
            bot.send_message_to_user(source, message_tokens, event, method='say')
        elif event.type == 'whisper':
            bot.send_message_to_user(source, message_tokens, event, method='whisper')

def load_settings(path):
    import os
    import sys
    sys.path.append(os.getcwd())

    def load_py_settings(path):
        config = {}
        execfile(path, {}, config)
        for key in config:
            setting = config[key]
            if isinstance(setting, dict) and key in settings:
                settings[key].update(setting)
            else:
                settings[key] = setting

    def load_yaml_settings(path):
        pass

    def load_json_settings(path):
        pass
    if path.endswith('.py'):
        load_py_settings(path)
    elif path.endswith('.json'):
        load_json_settings(path)
    else:
        load_yaml_settings(path)
    g.output_directory = os.path.abspath(settings.config.get('output'))
    g.static_directory = os.path.abspath(settings.config.get('static'))
    logging.info('Load Settings Finished')

def test_cholesky(self):

    def func(root, upper):
        x = 0.5 * (root + root.transpose(-1, -2).conj())
        return torch.cholesky(x, upper)

    def run_test(upper, dims, dtype):
        root = torch.rand(*dims, dtype=dtype, requires_grad=True)
        root = root + torch.eye(dims[-1])
        gradcheck(func, [root, upper])
        if not dtype.is_complex:
            gradgradcheck(func, [root, upper])
        root = torch.rand(*dims, dtype=dtype)
        root = torch.matmul(root, root.transpose(-1, -2).conj())
        root.requires_grad_()
        chol = root.cholesky().sum().backward()
        self.assertEqual(root.grad, root.grad.transpose(-1, -2).conj())
    for (upper, dims, dtype) in product([True, False], [(3, 3), (4, 3, 2, 2)], [torch.double, torch.cdouble]):
        run_test(upper, dims, dtype)

def init_asic_vlan_info(self, vlan_name):
    if vlan_name[0:4] != 'Vlan' or not vlan_name[4:].isnumeric():
        self.ret_temp['ASIC_DB']['tables_not_found'] = ['ASIC_STATE:SAI_OBJECT_TYPE_VLAN']
        return ({}, {})
    vlan_num = int(vlan_name[4:])
    req = MatchRequest(db='ASIC_DB', table='ASIC_STATE:SAI_OBJECT_TYPE_VLAN', key_pattern='*', field='SAI_VLAN_ATTR_VLAN_ID', value=str(vlan_num), ns=self.ns)
    ret = self.match_engine.fetch(req)
    self.add_to_ret_template(req.table, req.db, ret['keys'], ret['error'])

def _getEnsemblePaths(sourcePath, sourceProject):
    template = _looksLike(sourcePath, DefaultNames.EnsembleTemplate)
    if template:
        return dict(sourceDir=template[0], ensembleTemplate=template[1])
    template = _looksLike(sourcePath, DefaultNames.ServiceTemplate)
    if template:
        return dict(sourceDir=template[0], serviceTemplate=template[1])
    else:
        if os.path.isfile(sourcePath):
            template = _looksLike(sourcePath, DefaultNames.ServiceTemplate)
            if template:
                return dict(sourceDir=template[0], serviceTemplate=template[1])
        try:
            localEnv = LocalEnv(sourcePath, project=sourceProject)
            return dict(manifestPath=localEnv.manifestPath, localEnv=localEnv)
        except:
            return {}

def _get_needed_agent_based_modules(check_plugin_names: Set[CheckPluginName], inventory_plugin_names: Set[str]) -> List[str]:
    check_plugins_opt: List[Optional[CheckPlugin]] = [agent_based_register.get_check_plugin(p) for p in check_plugin_names]
    modules = {plugin.module for plugin in check_plugins_opt if plugin is not None and plugin.module is not None}
    modules.update((section.module for section in agent_based_register.get_relevant_raw_sections(check_plugin_names=check_plugin_names).values() if section.module is not None))
    section_plugins_opt = (agent_based_register.get_section_plugin(SectionName(name.split('.')[0])) for name in inventory_plugin_names)
    modules.update((section.module for section in section_plugins_opt if section is not None and section.module is not None))
    return sorted(modules)

def gotCalls(self, callList):
    debug('[FritzDisplayCalls] gotCalls')
    self.updateStatus(self.header + ' (' + str(len(callList)) + ')')
    sortlist = []
    noChars = scaleV(60, 40)
    for (number, date, remote, direct, here) in callList:
        while len(remote) + len(here) > noChars:
            if len(remote) > len(here):
                remote = remote[:-1]
            else:
                here = here[:-1]
            found = re.match('(\\d\\d.\\d\\d.)\\d\\d( \\d\\d:\\d\\d)', date)
            if found:
                date = found.group(1) + found.group(2)
            if direct == FBF_OUT_CALLS:
                message = date + ' ' + remote + ' -> ' + here
            else:
                message = date + ' ' + here + ' -> ' + remote
        sortlist.append([number, (eListboxPythonMultiContent.TYPE_TEXT, 0, 0, self.width - 10, 20, 0, RT_HALIGN_LEFT, message)])
    self['entries'].setList(sortlist)

def runDialog(self, dialog):
    if isinstance(dialog, dialogs.TextEntryDialog):
        dlog = TextEntryController.alloc().initWithDialog_(dialog)
        dlog.run()
        dialog.runCallback(dlog.result, dlog.value)
    elif isinstance(dialog, dialogs.HTTPAuthDialog):
        self.httpAuthLock.acquire()
        try:
            authDlog = PasswordController.alloc().initWithDialog_(dialog)
            result = authDlog.getAnswer()
            if result is not None:
                dialog.runCallback(dialogs.BUTTON_OK, *result)
            else:
                dialog.runCallback(None)
        finally:
            self.httpAuthLock.release()
    elif isinstance(dialog, dialogs.SearchChannelDialog):
        showWarningDialog('Not Implemented Error', 'The Search Channel dialog is now implemented. Please provide the necessary functionality.')
    else:
        buttons = map(lambda x: x.text, dialog.buttons)
        result = showWarningDialog(dialog.title, dialog.description, buttons)
        dialog.runCallback(dialog.buttons[result])

def __makenew__(self, *args, **kwargs):
    assert not args
    arguments = {'beam_specifier': self.beam_specifier, 'tie_across_divisions': self.tie_across_divisions}
    arguments.update(kwargs)
    maker = type(self)(**arguments)
    return maker

def validate(self, task):
    node = task.node
    missing_params = []
    task.driver.network.validate_rescue(task)
    if CONF.agent.manage_agent_boot:
        for req in RESCUE_PROPERTIES:
            if node.driver_info.get(req) is None:
                missing_params.append('driver_info/' + req)
    rescue_pass = node.instance_info.get('rescue_password')
    if rescue_pass is None:
        missing_params.append('instance_info/rescue_password')
    if missing_params:
        msg = _('Node %(node)s is missing parameter(s): %(params)s. These are required for rescuing node.')
        raise exception.MissingParameterValue(msg % {'node': node.uuid, 'params': ', '.join(missing_params)})
    if not rescue_pass.strip():
        msg = _("The 'instance_info/rescue_password' is an empty string for node %s. The 'rescue_password' must be a non-empty string value.") % node.uuid
        raise exception.InvalidParameterValue(msg)

